CREATE TABLE user_account(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,version bigint NOT NULL DEFAULT 0,created_at timestamptz NOT NULL,updated_at timestamptz NOT NULL,email varchar(254) not null unique,password_hash varchar(255),name varchar(160),role varchar(30),active boolean not null,last_login timestamptz);
CREATE TABLE partner(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,version bigint NOT NULL DEFAULT 0,created_at timestamptz NOT NULL,updated_at timestamptz NOT NULL,kind varchar(30),name varchar(160),company varchar(160),email varchar(254),phone varchar(60),address varchar(500),category varchar(100),active boolean not null);
CREATE TABLE operation(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,version bigint NOT NULL DEFAULT 0,created_at timestamptz NOT NULL,updated_at timestamptz NOT NULL,reference varchar(80) unique,type varchar(60),customer_id bigint references partner(id),origin varchar(160),destination varchar(160),estimated_date date,completed_at timestamptz,status varchar(30),assigned_id bigint references user_account(id),description varchar(4000),created_by bigint references user_account(id));
CREATE TABLE operation_history(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,version bigint NOT NULL DEFAULT 0,created_at timestamptz NOT NULL,updated_at timestamptz NOT NULL,operation_id bigint references operation(id),actor_id bigint references user_account(id),event varchar(100),detail varchar(2000));
CREATE TABLE inventory_item(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,version bigint NOT NULL DEFAULT 0,created_at timestamptz NOT NULL,updated_at timestamptz NOT NULL,sku varchar(80) unique,name varchar(160),description varchar(4000),category varchar(100),quantity integer not null check(quantity>=0),minimum_stock integer not null check(minimum_stock>=0),unit varchar(30),location varchar(160),active boolean not null);
CREATE TABLE inventory_movement(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,version bigint NOT NULL DEFAULT 0,created_at timestamptz NOT NULL,updated_at timestamptz NOT NULL,item_id bigint references inventory_item(id),actor_id bigint references user_account(id),delta integer not null,reason varchar(500),balance integer not null);
CREATE TABLE document_record(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,version bigint NOT NULL DEFAULT 0,created_at timestamptz NOT NULL,updated_at timestamptz NOT NULL,filename varchar(255),type varchar(60),description varchar(2000),operation_id bigint references operation(id),uploaded_by bigint references user_account(id),size bigint not null,content_type varchar(100),status varchar(30),content bytea);
CREATE TABLE audit_log(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,version bigint NOT NULL DEFAULT 0,created_at timestamptz NOT NULL,updated_at timestamptz NOT NULL,actor_id bigint references user_account(id),action varchar(100),entity varchar(100),entity_id bigint,detail varchar(2000));
CREATE TABLE company_setting(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,version bigint NOT NULL DEFAULT 0,created_at timestamptz NOT NULL,updated_at timestamptz NOT NULL,company_name varchar(160),timezone varchar(100),support_email varchar(254));
CREATE INDEX operation_assignee ON operation(assigned_id); CREATE INDEX operation_date ON operation(created_at); CREATE INDEX document_operation ON document_record(operation_id); CREATE INDEX audit_date ON audit_log(created_at);
CREATE TABLE SPRING_SESSION(PRIMARY_ID CHAR(36) PRIMARY KEY,SESSION_ID CHAR(36) NOT NULL,CREATION_TIME BIGINT NOT NULL,LAST_ACCESS_TIME BIGINT NOT NULL,MAX_INACTIVE_INTERVAL INT NOT NULL,EXPIRY_TIME BIGINT NOT NULL,PRINCIPAL_NAME VARCHAR(100));
CREATE UNIQUE INDEX SPRING_SESSION_IX1 ON SPRING_SESSION(SESSION_ID);CREATE INDEX SPRING_SESSION_IX2 ON SPRING_SESSION(EXPIRY_TIME);CREATE INDEX SPRING_SESSION_IX3 ON SPRING_SESSION(PRINCIPAL_NAME);
CREATE TABLE SPRING_SESSION_ATTRIBUTES(SESSION_PRIMARY_ID CHAR(36) NOT NULL REFERENCES SPRING_SESSION(PRIMARY_ID) ON DELETE CASCADE,ATTRIBUTE_NAME VARCHAR(200) NOT NULL,ATTRIBUTE_BYTES BYTEA NOT NULL,PRIMARY KEY(SESSION_PRIMARY_ID,ATTRIBUTE_NAME));
